  parsePortConn() {
    if (this.atOp('.')) {
      this.next();
      const port = this.expectIdent();
      this.expectOp('(');
      const expr = this.parseExpr();
      this.expectOp(')');
      return { port, expr };
    }
    return { port: null, expr: this.parseExpr() };
  }

  /* Returns the WIDTH the simulator runs on plus the msb/lsb exactly AS WRITTEN,
     both null for a scalar. The width expression is untouched: everything
     downstream (declareSignal, maskVal, widthOfExpr, the radix menu) still sees
     the same bit count it always did, and nothing in the engine reads msb/lsb at
     all - they exist only so the Module Hierarchy panel and the waveform's name
     column can print `d[4:1]` for a signal declared `reg [4:1] d;` rather than
     the `d[3:0]` a width-derived label would invent. Deriving the label from the
     width is right for every declaration in EXAMPLES (all are [N-1:0]) and wrong
     for any design that indexes from something other than 0, which is precisely
     the kind of plausible-looking wrong number this panel must not show. */
  parseRange() {
    if (this.atOp('[')) {
      this.next();
      const hi = this.parseExpr();
      this.expectOp(':');
      const lo = this.parseExpr();
      this.expectOp(']');
      const msb = evalConstExpr(hi, this.curModule, this.params);
      const lsb = evalConstExpr(lo, this.curModule, this.params);
      /* A NEGATIVE bound is refused rather than measured. `Math.abs(msb - lsb) + 1`
         turns `[-1:0]` into a perfectly healthy-looking 2-bit register, and that
         range is not hypothetical now that $clog2 exists: $clog2(1) is 0 per the
         LRM, so the ordinary `[$clog2(DEPTH)-1:0]` idiom produces exactly it for
         DEPTH = 1. A one-deep memory addressed by zero bits is a nonsensical
         configuration and every real tool rejects the declaration; measuring it
         as two bits is the one answer that lets the design keep running while
         being wrong about its own width. */
      if (msb < 0 || lsb < 0) {
        throw new Error(`Parse error at line ${this.peek().line}: bit range [${msb}:${lsb}] has a negative bound`
          + (msb < 0 && lsb === 0 ? ' - $clog2(1) is 0, so a depth of 1 needs no address bits' : ''));
      }
      return { width: Math.abs(msb - lsb) + 1, msb, lsb };
    }
    return { width: 1, msb: null, lsb: null };
  }

  // A second `[first:second]` following a declared name makes it a memory
  // (`reg [7:0] mem[0:15];`) - kept in DECLARATION order (not normalized to
  // hi/lo) since $readmemh's default fill address/direction is defined in
  // terms of the first index as written, not numeric magnitude.
  parseArrayRange() {
    if (!this.atOp('[')) return null;
    this.next();
    const firstExpr = this.parseExpr();
    this.expectOp(':');
    const secondExpr = this.parseExpr();
    this.expectOp(']');
    return { first: evalConstExpr(firstExpr, this.curModule, this.params), second: evalConstExpr(secondExpr, this.curModule, this.params) };
  }

  // `parameter NAME = expr;` - expr must be a constant expression, validated
  // eagerly here (via evalConstExpr, the same one used for range/array bounds
  // and replication counts) so a bad parameter definition fails at its own
  // declaration rather than wherever it happens to be used. The expression
  // NODE itself (not just its folded value) is what gets stored, keyed by
  // module name like this.arrayDecls - substituting the node wherever the
  // parameter is referenced (see parsePrimary) is what lets a parameter be
  // used in ANY expression context, not just the three constant-only ones
  // evalConstExpr covers, and keeps a 4-state literal's x/z bits intact for
  // e.g. a casex label (`parameter ADD = 3'b10?;`) instead of collapsing it
  // to evalConstExpr's known-bits-only integer.
  //
  // `localparam` is accepted as a SYNONYM, and the fact that it is one is a
  // statement about this subset rather than laziness: what localparam actually
  // means is "not overridable from outside", and per-instance overrides
  // (`#(.WIDTH(8))`) are not supported here at all - so there is no context in
  // which the two could behave differently. If overrides ever land, this is the
  // one place that has to start telling them apart, and an override aimed at a
  // localparam has to be refused rather than silently applied.
